export function evaluate({ inputs, time }) {
  const g = 9.8;
  const u = inputs.launchSpeed;
  const T = 2 * u / g;
  const t = Math.min(Math.max(time, 0), T);
  const tap = u / g;
  const hAp = u * u / (2 * g);
  const v = u - g * t;
  const h = Math.max(0, u * t - g * t * t / 2);
  const y0 = 370, top = 70;
  const sc = (y0 - top) / 1.4;
  const by = y0 - h * sc;
  const bx = 280;
  const eps = 0.02;
  let state = 'Moving up';
  if (Math.abs(v) < eps) state = 'Still for an instant';
  else if (v < 0) state = 'Moving down';
  const objs = [];
  objs.push(...sdk.panel({ x: 20, y: 40, w: 600, h: 365, title: 'Tossed ball', state: state, id: 'lane.toss' }));
  objs.push(sdk.axis('axis.h', { x: 100, y: y0, length: 300, orientation: 'y', min: 0, max: 1.4, ticks: [0, 0.4, 0.8, 1.2], label: 'Height', unit: 'm' }));
  objs.push(sdk.line('guide.launch', 110, y0, 450, y0, { role: 'neutral' }));
  objs.push(sdk.circle('ball.toss', bx, by - 14, 28, { role: 'output' }));
  const vs = Math.abs(v) < eps ? 0 : v;
  objs.push(...sdk.vector('vec.v', { x: bx - 40, y: by - 14 }, { value: vs, direction: 'up' }, { scale: 14, label: 'v', role: 'input' }));
  objs.push(...sdk.vector('vec.a', { x: bx + 40, y: by - 14 }, { value: -g, direction: 'up' }, { scale: 5, label: 'a', role: 'warning' }));
  objs.push(...sdk.callout(470, 160, [state, 'Gravity pulls down'], { id: 'callout.toss' }));
  return {
    frame: { width: 640, height: 420, objects: objs, readouts: [{ id: 'motionState', value: state }, { id: 'gravityState', value: 'Gravity pulls down' }] },
    quantities: { launchSpeed: u, gravity: g, apexTime: tap, apexHeight: hAp, velocity: v, height: h }
  };
}
